const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-0.819876, 53.083908]);
  const roi = point.buffer(5000); // 5 km radius

  const date2022 = '2022-01-05';
  const date2024 = '2024-01-04';

  // 2. Data Acquisition - Sentinel-1 SAR
  const s1_2022 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(roi)
    .filterDate(date2022, ee.Date(date2022).advance(1, 'day'))
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .select('VV');

  const s1_2024 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(roi)
    .filterDate(date2024, ee.Date(date2024).advance(1, 'day'))
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .select('VV');

  const count2022 = s1_2022.size().getInfo();
  const count2024 = s1_2024.size().getInfo();

  console.log(`2022 Images: ${count2022}`);
  console.log(`2024 Images: ${count2024}`);

  // Check if collections are empty - try wider date range if needed
  if (count2022 === 0 || count2024 === 0) {
    console.log("Trying wider date range (+/- 3 days)...");

    const s1_2022_wide = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(roi)
      .filterDate('2022-01-02', '2022-01-08')
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .select('VV');

    const s1_2024_wide = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(roi)
      .filterDate('2024-01-01', '2024-01-07')
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .select('VV');

    const count2022_wide = s1_2022_wide.size().getInfo();
    const count2024_wide = s1_2024_wide.size().getInfo();

    console.log(`2022 Wide Images: ${count2022_wide}`);
    console.log(`2024 Wide Images: ${count2024_wide}`);

    if (count2022_wide === 0 || count2024_wide === 0) {
      console.log("No data available for comparison.");
      console.log("<answer>C1</answer>");
      return;
    }

    // Use wider range data
    var img2022 = s1_2022_wide.mosaic();
    var img2024 = s1_2024_wide.mosaic();
  } else {
    var img2022 = s1_2022.mosaic();
    var img2024 = s1_2024.mosaic();
  }

  // 3. Water Detection - VV < -15 dB indicates water
  const water2022 = img2022.lt(-15);
  const water2024 = img2024.lt(-15);

  // 4. Calculate water extent (pixel count)
  const waterStats2022 = water2022.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const waterStats2024 = water2024.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const waterPixels2022 = waterStats2022.get('VV_sum').getInfo();
  const totalPixels2022 = waterStats2022.get('VV_count').getInfo();
  const waterPixels2024 = waterStats2024.get('VV_sum').getInfo();
  const totalPixels2024 = waterStats2024.get('VV_count').getInfo();

  console.log(`2022: Water pixels: ${waterPixels2022}, Total pixels: ${totalPixels2022}`);
  console.log(`2024: Water pixels: ${waterPixels2024}, Total pixels: ${totalPixels2024}`);

  // 5. Validation & Final Answer
  if (waterPixels2022 === null || waterPixels2024 === null) {
    console.log("Calculation failed - null result.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (totalPixels2022 === 0 || totalPixels2024 === 0) {
    console.log("No valid pixels in ROI.");
    console.log("<answer>C2</answer>");
    return;
  }

  const waterArea2022 = waterPixels2022 * 1000000; // pixels * scale^2 (m²)
  const waterArea2024 = waterPixels2024 * 1000000;

  console.log(`2022 Water extent: ${(waterArea2022 / 1e6).toFixed(2)} km²`);
  console.log(`2024 Water extent: ${(waterArea2024 / 1e6).toFixed(2)} km²`);

  if (waterPixels2024 > waterPixels2022) {
    console.log("Water extent was larger on January 4, 2024.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Water extent was NOT larger on January 4, 2024.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
